package nl.smartstreamlabs.sbwdroneconfig;
import com.mojang.blaze3d.vertex.*;import net.minecraft.client.*;import net.minecraft.client.renderer.*;import net.minecraft.core.Direction;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.phys.Vec3;import org.joml.Vector3f;import software.bernie.geckolib.cache.object.*;import java.util.*;import java.io.*;
/** One resident mesh batch per installation model; only its pose palette changes. */
public final class Ndc01Model{
 private static Ndc01Model CACHE;private final GeoCube[]cubes;private final BakedGeoModel model;private final ResourceLocation texture;public static Ndc01Model get(){if(CACHE==null)CACHE=new Ndc01Model();return CACHE;}public static void clear(){if(CACHE!=null){Adv01Gpu.release(CACHE.model);CACHE=null;}}
 private Ndc01Model(){var geo=Ndc01Geometry.MODEL;texture=ResourceLocation.tryParse("sbwdroneconfig:ndc01/carrier.png");cubes=new GeoCube[geo.bones.size()];var bones=new ArrayList<GeoBone>();try(var in=new DataInputStream(Minecraft.getInstance().getResourceManager().getResourceOrThrow(ResourceLocation.tryParse("sbwdroneconfig:ndc01/carrier.bin")).open())){if(in.readInt()!=0x464c3031||in.readInt()!=cubes.length)throw new IOException("Defense mesh header");for(int n=0;n<cubes.length;n++){int count=in.readInt();if(count<0||count>50000)throw new IOException("Defense mesh length");var quads=new GeoQuad[count];for(int f=0;f<count;f++){var normal=new Vector3f(in.readFloat(),in.readFloat(),in.readFloat());var vertices=new GeoVertex[4];for(int k=0;k<4;k++)vertices[k]=new GeoVertex(in.readFloat(),in.readFloat(),in.readFloat()).withUVs(in.readFloat(),in.readFloat());quads[f]=new GeoQuad(vertices,normal,Direction.getNearest(normal.x,normal.y,normal.z));}if(count>0){cubes[n]=new GeoCube(quads,Vec3.ZERO,Vec3.ZERO,new Vec3(1,1,1),0,false);MeshRenderData.register(cubes[n]);var bone=new GeoBone(null,geo.bones.get(n).name(),false,0d,false,false);bone.getCubes().add(cubes[n]);bones.add(bone);}}if(in.read()!=-1)throw new IOException("Defense trailing bytes");}catch(IOException e){throw new IllegalStateException("Cannot load "+"NDC-01",e);}model=new BakedGeoModel(bones,null);}
 public void draw(Ndc01Entity entity,float partial,PoseStack p,MultiBufferSource buffers,int light,int overlay){var poses=Ndc01Geometry.MODEL.transforms(entity,partial);var type=RenderType.entityCutoutNoCull(texture);var batch=(buffers instanceof MultiBufferSource.BufferSource||WhiteHotRender.gpuSource(buffers))?Adv01Gpu.batch(model):null;float r=1,g=1,b=1,a=1;if(batch!=null)batch.begin();for(int i=0;i<cubes.length;i++)if(cubes[i]!=null){p.pushPose();p.last().pose().mul(new org.joml.Matrix4f(poses[i]));p.last().normal().mul(new org.joml.Matrix3f(new org.joml.Matrix4f(poses[i])));if(batch!=null)batch.pose(cubes[i],p);else emit(p,buffers.getBuffer(type),MeshRenderData.get(cubes[i]),light,overlay,r,g,b,a);p.popPose();}if(batch!=null){if(WhiteHotRender.gpuSource(buffers))WhiteHotRender.captureGpu(buffers,batch,type,a);else batch.draw(type,light,overlay,r,g,b,a);}}
 private static void emit(PoseStack poses,VertexConsumer consumer,MeshRenderData data,int light,int overlay,float red,float green,float blue,float alpha){var m=poses.last().pose();var n=poses.last().normal();var v=data.values;if(MeshBulkWriter.draw(consumer,data,m,n,light,overlay,red,green,blue,alpha))return;for(int at=0;at<v.length;at+=23){float a=v[at],b=v[at+1],c=v[at+2];float nx=n.m00()*a+n.m10()*b+n.m20()*c,ny=n.m01()*a+n.m11()*b+n.m21()*c,nz=n.m02()*a+n.m12()*b+n.m22()*c;for(int i=at+3;i<at+23;i+=5){float x=v[i],y=v[i+1],z=v[i+2];float px=m.m00()*x+m.m10()*y+m.m20()*z+m.m30(),py=m.m01()*x+m.m11()*y+m.m21()*z+m.m31(),pz=m.m02()*x+m.m12()*y+m.m22()*z+m.m32();consumer.vertex(px,py,pz,red,green,blue,alpha,v[i+3],v[i+4],overlay,light,nx,ny,nz);}}}
}
